/* the game's language number (Manager+0x564f8) -> the set; -1 means English */
static int tw_set_for_language(int language) {
    switch (language) {
        case 0: return 0;
        case 2: return 4;
        case 3: return 0;
        case 4: return 3;
        case 5: return 2;
        case 10: return 1;
        case 11: return 5;
        case 13: return 6;
        default: return 0;
    }
}

